#!/usr/bin/env node
/**
 * Number-plate renderer for Financial Gurkha reels and carousels.
 *
 * The hard number in a video is composited, never generated by Midjourney.
 * This renders that number as a transparent 1080×1920 PNG overlay in the house
 * style, so every "$24B" or "8.6×" looks the same across every video.
 *
 *   npm run plate -- --number "$24B" --label "Wiped off Moderna in one afternoon"
 *   npm run plate -- --number "8.6×" --label "ML model breaches in stress" --kicker "When backtests lie" --out plates/86x.png
 *   npm run plate -- --number "$2T" --label "Anthropic's IPO target" --position center --format carousel
 *
 * Options
 *   --number    the number, exactly as it should read (required)
 *   --label     one short line under the number (optional, ~45 characters max)
 *   --kicker    small gold line above the number (optional)
 *   --position  low (default: just above the subtitle band) | center | high
 *   --format    reel (1080×1920, default) | carousel (1080×1350) | square (1080×1080)
 *   --out       output path (default: plates/plate-<number>.png)
 *
 * Needs Chrome or Brave. Set CHROME_PATH if it is not in the default macOS location.
 */
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { PALETTE } from '../brand/style.mjs'

const args = process.argv.slice(2)
const opt = (name, fallback = '') => {
  const i = args.indexOf(`--${name}`)
  return i >= 0 && args[i + 1] !== undefined ? args[i + 1] : fallback
}

const number = opt('number')
if (!number) {
  console.error('Missing --number. Example: npm run plate -- --number "$24B" --label "Wiped off Moderna"')
  process.exit(1)
}
const label = opt('label')
const kicker = opt('kicker')
const position = opt('position', 'low')
const format = opt('format', 'reel')

const SIZES = { reel: [1080, 1920], carousel: [1080, 1350], square: [1080, 1080] }
if (!SIZES[format]) {
  console.error(`Unknown --format "${format}". Use reel, carousel or square.`)
  process.exit(1)
}
const [W, H] = SIZES[format]

/*
 * Vertical placement. For reels, "low" puts the plate just above the subtitle
 * band and clear of the platform UI: Instagram and TikTok overlay captions and
 * buttons on roughly the bottom 20–25% of the frame. The plate's bottom edge
 * sits ~430px above the frame bottom, leaving room for burned-in subtitles
 * beneath it.
 */
const BOTTOM_GAP = { reel: { low: 430, center: null, high: null }, carousel: { low: 140 }, square: { low: 120 } }
const gap = (BOTTOM_GAP[format] || {})[position]
const placement =
  position === 'center' || gap === undefined
    ? 'top:50%; transform:translate(-50%,-50%);'
    : position === 'high'
      ? `top:${Math.round(H * 0.18)}px; transform:translateX(-50%);`
      : `bottom:${gap}px; transform:translateX(-50%);`

const fontsDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../brand/video/fonts')
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
// Long numbers shrink so they always fit on one line.
const numberSize = Math.min(300, Math.floor((W * 0.86) / Math.max(3, number.length * 0.62)))

const html = `<!doctype html><html><head><meta charset="utf-8"><style>
  @font-face{font-family:"FG Serif";src:url("file://${fontsDir}/PlayfairDisplay.ttf");font-weight:400 900;}
  @font-face{font-family:"FG Sans";src:url("file://${fontsDir}/Inter-Black.otf");font-weight:900;}
  html,body{margin:0;background:transparent;}
  .frame{position:relative;width:${W}px;height:${H}px;overflow:hidden;}
  .plate{position:absolute;left:50%;${placement}
    display:flex;flex-direction:column;align-items:center;gap:18px;
    padding:34px 56px 38px;border-radius:28px;max-width:${Math.round(W * 0.88)}px;
    background:linear-gradient(180deg,rgba(8,8,8,0.82),rgba(8,8,8,0.94));
    border:3px solid ${PALETTE.gold};
    box-shadow:0 24px 60px rgba(0,0,0,0.5), 0 0 60px rgba(200,160,72,0.25);}
  .kicker{font:900 30px/1 "FG Sans",-apple-system,"Helvetica Neue",Arial,sans-serif;letter-spacing:7px;
    text-transform:uppercase;color:${PALETTE.gold};}
  .number{font:900 ${numberSize}px/0.92 "FG Serif",Georgia,serif;color:${PALETTE.goldBright};letter-spacing:-2px;
    white-space:nowrap;text-shadow:0 2px 0 rgba(0,0,0,0.35),0 0 30px rgba(232,192,98,0.35);}
  .label{font:900 44px/1.2 "FG Sans",-apple-system,"Helvetica Neue",Arial,sans-serif;color:${PALETTE.white};
    text-align:center;max-width:${Math.round(W * 0.78)}px;}
</style></head><body><div class="frame"><div class="plate">
  ${kicker ? `<div class="kicker">${esc(kicker)}</div>` : ''}
  <div class="number">${esc(number)}</div>
  ${label ? `<div class="label">${esc(label)}</div>` : ''}
</div></div></body></html>`

const slug = number.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase() || 'plate'
const out = path.resolve(opt('out', `plates/plate-${slug}.png`))
fs.mkdirSync(path.dirname(out), { recursive: true })

const tmp = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'fg-plate-')), 'plate.html')
fs.writeFileSync(tmp, html)

const browser =
  process.env.CHROME_PATH ||
  [
    '/Applications/Brave Browser.app/Contents/MacOS/Brave Browser',
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    '/Applications/Chromium.app/Contents/MacOS/Chromium',
    '/usr/bin/google-chrome',
    '/usr/bin/chromium',
    '/usr/bin/chromium-browser',
  ].find((p) => fs.existsSync(p))
if (!browser) {
  console.error('No Chrome or Brave found. Set CHROME_PATH to a Chromium-based browser.')
  process.exit(1)
}

execFileSync(
  browser,
  [
    '--headless=new',
    '--disable-gpu',
    // Chrome refuses to run as root (containers, CI) unless its sandbox is off
    ...(process.getuid && process.getuid() === 0 ? ['--no-sandbox'] : []),
    '--allow-file-access-from-files',
    '--virtual-time-budget=3000', // let the bundled fonts load before the screenshot
    '--hide-scrollbars',
    '--default-background-color=00000000', // transparent PNG
    '--force-device-scale-factor=1',
    `--window-size=${W},${H}`,
    `--screenshot=${out}`,
    `file://${tmp}`,
  ],
  { stdio: 'ignore' }
)
console.log(`Plate written: ${path.relative(process.cwd(), out)} (${W}×${H}, transparent)`)
